architecture.h4_f:
msg = CBOR{v:1, tekst, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, tekst, reply_to?, thread_id?, mentions?, sent_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
žica = CBOR{
  v: 1,
  šifrirani tekst: hex(ct), // promjenjiva duljina
  jednokratno: hex(12 B),
  pseudo_pošiljatelja: hex(16 B),
  poslano_na: unix_ms
}

cryptoWire.h5_f:
vanjski = CBOR{
  izvorni_čvor: hex32,
  target_user: int64,
  unutarnji_šifrirani tekst: bajtovi,
  inner_nonce: bajtovi,
  poslano_na: unix_ms
}
sig = Ed25519-Sign(source_priv, vanjski)
POST /federation/deliver { kuverta: vanjska, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { korisničko ime, lozinka, x25519_javni_ključ, prikazno_ime, telefon?, e-pošta?, avatar_emoji }

Odgovor 201 Kreiran:
  { access_token, refresh_token, user_id, korisničko ime, ... }

auth.h3_f:
access_token korisni teret:
  { sub: user_id, jti: device_id, typ: "access", exp: sada + 15 min }
teret refresh_token:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-potpisano 64-bajtnom tajnom čvora iz .env

auth.h4_f:
register_begin(): izazov = rand(32)
                    opcije = {rp.id, user.id, pubKeyCredParams, izazov}
                    mogućnosti vraćanja

registar_završetak (potvrda):
  potvrdite potvrdu prema TPM / Secure Enclave root CA
  pohrani { id_vjerodajnice, javni_ključ, brojač: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → registriran novi uređaj; JWT-ovi su se vratili.

rooms.h6_f:
pseudo_pošiljatelja = HMAC-SHA256(pseudo_soba_soli, id_pošiljatelja)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Fan-out okvir: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {upload_id, chunk_size}
komad PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finaliziraj POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL na nedovršeno: 24 h

files.h4_f:
popis_zabrana = {
  "aplikacija/x-dosexec",
  "aplikacija/x-sharedlib",
  "aplikacija/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) u deny_list: vrati 415

presence.h1_f:
klijent: na prvi pritisak tipke → pošalji {type:"t", state:"start"}
         nema više slanja 3 s osim ako se stanje ne promijeni
         10 s nakon zadnjeg pritiska tipke → pošalji {type:"t", state:"stop"}
prijemnik: auto-stop 10 s nakon zadnjeg "starta" ako nije stigao "stop".

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS emitiranje {type:"c", kind:"invite", call_id}
WS emitiranje {type:"c", kind:"offer", sdp}
WS emitiranje {type:"c", kind:"answer", sdp}
WS emitiranje {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
omotnica = {
  izvorni_čvor: hex32,
  ciljni_korisnik: int64,
  unutarnji_šifrirani tekst: bajtovi,
  inner_nonce : bajtovi,
  sent_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(omotnica))
POST /federation/deliver { kuverta, sig }

gossip.h3_f:
oglas = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(oglas))
sadržaj ogovaranja: [..., {ad, sig}, ...]

primatelj: potvrdi sig prema ad.pubkey → pohrani ako je ok
dodatno: PoW od 2^18 vodećih nula na {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template with {
  random = naš random,
  server_name = naš hostname (ili omotan ECH),
  session_id = naš ID sesije,
}
JA4 = t13d_xxxx_xxxx_xxxx (podudara se s trenutnom Chrome stabilnom)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(javni_ključ_iz_HTTPS_zapisa)
DGA: domena(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
alat = znak_alat
input = izvorno stablo, ključevi/release.key
manifest = {
  verzija: "0.1.0",
  izgrađen_na: unix_ms,
  datoteke: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
izlaz = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
kreiraj: POST /api/bots {korisničko ime, ime za prikaz, kod}
          → {bot_id, token, pubkey}
izvođenje: u procesu (korutina unutar čvora)
      OR vanjski (long-poll /api/bots/{id}/updates, token-auth'd)
poruka: {tekst, potpis: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
na /start {
  emitiraj "Dobro došli, {ctx.first_name}"
}
on /add <item> {
  state.list = (state.list ili []) + [ctx.args.item]
  emitiraj "Dodano: {ctx.args.item}"
}

security.h4_f:
canary.txt (svakodnevno):
  {datum, sig: Ed25519-Sign(release_priv, date)}
klijent provjerava → odsutan ili nevažeći ⇒ sumnja na kompromitaciju

hitno:
  admin POST /api/admin/revoke-all {razlog}
  emitiranje čvora {type:"n", event:"compromise", reason}
  klijenti brišu ključeve, prisiljavaju ponovno podizanje sustava

debugging.h2_f:
histogrami brzine (po ruti + metoda):
  vortex_http_requests_total{ruta,metoda,status}
  vortex_http_request_duration_seconds_bucket{ruta,metoda,le}

websocket mjerači:
  vortex_ws_connections{čvor}
  vortex_ws_fanout_queue_depth{soba,korisnik}

prilagođeni brojači:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{vrsta}

login.h3_f:
{
  "korisničko ime": "alisa",
  "lozinka": "ispravna spajalica za konjske baterije",
  "totp": "123456" // potrebno ako je 2FA omogućen
